import numpy as np
A=np.array(grid); out=A.copy(); H,W=A.shape
for r in range(H):
    cs=np.where(A[r]==2)[0]
    if len(cs)>1:
        out[r,cs.min():cs.max()+1][out[r,cs.min():cs.max()+1]==5]=3
for c in range(W):
    rs=np.where(A[:,c]==2)[0]
    if len(rs)>1:
        sl=out[rs.min():rs.max()+1,c]
        sl[sl==5]=3
print('\n'.join(' '.join(map(str,row)) for row in out))
print('Changed:',list(zip(*np.where(out==3))))

# Set current parsed test data and enumerate every pairwise axis alignment/gap to reason about possible selection.
for r in range(H):
    cs=list(np.where(A[r]==2)[0]+1)
    print('row',r+1,cs)
for c in range(W):
    rs=list(np.where(A[:,c]==2)[0]+1)
    if len(rs)>1: print('col',c+1,rs)
